const helpV5=showHelp;showHelp=function(){helpV5();const incense=[...$('#modal-content').querySelectorAll('section')].find(s=>s.querySelector('b')?.textContent==='Incenso');if(incense)incense.querySelector('p').textContent='Ative na Mochila. Por 1 hora, uma nova aparição é gerada a cada 5 minutos.'};
const pokemonStatusWithoutTypes=pokemonStatus;
pokemonStatus=async uid=>{const p=findOwned(uid);if(p&&!Array.isArray(p.types))try{p.types=(await pokemon(p.id)).types;persist()}catch{p.types=[]}await pokemonStatusWithoutTypes(uid);const head=$('#modal-content .pokemon-status-head>div');if(head&&p&&!head.querySelector('.type-icons'))head.insertAdjacentHTML('beforeend',`${typeIcons(p.types)}<small class="pokemon-gender">${genderLabel(p.gender)}</small>`)};
