rooms=async()=>{roomsWithoutTypes();await hydrateOwnedTypes();if(currentView!=='rooms')return;document.querySelectorAll('[data-statusuid]').forEach(button=>{const p=findOwned(button.dataset.statusuid),card=button.closest('.poke-room,.box-mon');if(card&&p&&!card.querySelector('.type-icons'))card.querySelector('small')?.insertAdjacentHTML('afterend',`${typeIcons(p.types)}<small class="pokemon-gender">${genderLabel(p.gender)}</small>`)})};
const profileWithoutOwnedFilter=profileView;
profileView=async()=>{const ownedOnly=titleFilter==='Meus títulos';if(ownedOnly)titleFilter='Todos';await profileWithoutOwnedFilter();if(currentView!=='profile')return;if(ownedOnly)titleFilter='Meus títulos';const filters=$('.title-filters');if(!filters)return;filters.insertAdjacentHTML('afterbegin',`<button class="${ownedOnly?'active':''}" data-title-filter="Meus títulos">Meus títulos</button>`);if(ownedOnly){filters.querySelector('[data-title-filter="Todos"]')?.classList.remove('active');document.querySelectorAll('.title-card.locked').forEach(card=>card.remove())}};
const originalPlanExpedition=planExpedition;
planExpedition=function(event,p,chance){const plan=originalPlanExpedition(event,p,chance);if(!['partial','success','great'].includes(plan.result))return plan;const ranges={partial:[3,6],success:[Math.max(7,Math.floor(chance/8)),Math.min(18,Math.max(11,Math.floor(chance/5)+1))],great:[14,20]},[min,max]=ranges[plan.result],count=min+Math.floor(Math.random()*(max-min+1)),allowed=event.species.filter(s=>plan.result==='great'||plan.result==='success'&&s.tier!=='very-rare'||plan.result==='partial'&&s.tier==='common'),weights={common:10,uncommon:6,rare:2,'very-rare':.5};plan.rescues=[];for(let i=0;i<count;i++){const total=allowed.reduce((n,s)=>n+weights[s.tier],0);let roll=Math.random()*total,spec=allowed.find(s=>(roll-=weights[s.tier])<=0)||allowed[0];plan.rescues.push({rescueId:`r${Date.now()}-${i}-${Math.random().toString(16).slice(2)}`,id:spec.id,eventId:event.id,tier:spec.tier,shiny:Math.floor(Math.random()*200)===0,fed:null,selectedBall:null})}return plan};
const genderFromRate=(id,rate)=>Number(id)===132||rate===-1?'genderless':rate===0?'male':rate===8?'female':Math.random()*8<rate?'female':'male';
const genderLabel=g=>g==='male'?'♂ Macho':g==='female'?'♀ Fêmea':'Sem gênero';
const highChanceExpeditionPlan=planExpedition;
planExpedition=function(event,p,chance){const plan=highChanceExpeditionPlan(event,p,chance);if(chance<90||!['partial','success','great'].includes(plan.result))return plan;if(plan.result==='partial')plan.result='success';const target=12+Math.floor(Math.random()*7),allowed=event.species.filter(s=>s.tier!=='very-rare'),weights={common:10,uncommon:6,rare:2},total=allowed.reduce((n,s)=>n+weights[s.tier],0);while(plan.rescues.length<target){let roll=Math.random()*total,spec=allowed.find(s=>(roll-=weights[s.tier])<=0)||allowed[0],i=plan.rescues.length;plan.rescues.push({rescueId:`r${Date.now()}-bonus-${i}-${Math.random().toString(16).slice(2)}`,id:spec.id,eventId:event.id,tier:spec.tier,shiny:Math.floor(Math.random()*200)===0,fed:null,selectedBall:null})}return plan};
const breedingParent=uid=>ownedPokemon().find(p=>p.uid===uid);
const onBreeding=p=>!!p&&!!state.breeding&&[state.breeding.parentA,state.breeding.parentB].includes(p.uid);
const breedingTime=ms=>{const sec=Math.max(0,Math.ceil(ms/1000));return`${String(Math.floor(sec/3600)).padStart(2,'0')}:${String(Math.floor(sec%3600/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`};
async function breedingView(){const root=$('#view-container');root.innerHTML='<div class="panel"><h2>Preparando Centro de Breeding...</h2></div>';await hydrateOwnedTypes();if(currentView!=='breeding')return;const breed=state.breeding;if(!breed){const eligible=ownedPokemon().filter(p=>p.id===132||p.gender!=='genderless');root.innerHTML=`<div class="view-title"><div><h1>Centro de Breeding</h1><p>Forme um casal ou use Ditto como coringa para produzir um ovo.</p></div><span>Ovo em 24 horas</span></div><div class="breeding-setup panel"><h2>Escolher parceiros</h2><p>Selecione Pokémon diferentes. O filhote será da espécie da fêmea; com Ditto, será da espécie do outro parceiro.</p><label>Primeiro parceiro<select id="breed-first"><option value="">Escolher...</option>${eligible.map(p=>`<option value="${p.uid}">${p.nickname} · ${genderLabel(p.gender)}</option>`).join('')}</select></label><label>Segundo parceiro<select id="breed-second"><option value="">Escolher...</option>${eligible.map(p=>`<option value="${p.uid}">${p.nickname} · ${genderLabel(p.gender)}</option>`).join('')}</select></label><button class="primary-button" id="start-breeding">Iniciar breeding</button></div>`;$('#start-breeding').onclick=()=>startBreeding($('#breed-first').value,$('#breed-second').value);return}const a=breedingParent(breed.parentA),b=breedingParent(breed.parentB),now=Date.now(),eggReady=now>=breed.eggAt,incubating=Number.isFinite(breed.hatchAt),hatched=incubating&&now>=breed.hatchAt,cooldown=Math.max(0,(breed.lastFedAt||0)+3600000-now),berries=ITEMS.filter(i=>i.type==='food'&&(state.inventory[i.id]||0)&&i.favored.some(t=>breed.offspringTypes.includes(t)));root.innerHTML=`<div class="view-title"><div><h1>Centro de Breeding</h1><p>${incubating?'O ovo está na incubadora.':'Os parceiros estão cuidando do ninho.'}</p></div><span>${hatched?'Pronto para chocar':incubating?'Incubando':'Produzindo ovo'}</span></div><div class="breeding-active panel"><div class="breeding-parents">${[a,b].map(p=>`<article><img src="${spriteFor(p)}" alt="${p?.name||''}"><b>${p?.nickname||'Pokémon'}</b><small>${genderLabel(p?.gender)}</small></article>`).join('<strong>♥</strong>')}</div>${!incubating?`<div class="breeding-egg"><img src="${itemSprite('lucky-egg')}" alt="Ovo Pokémon"><h2>${eggReady?'O ovo está pronto!':'Tempo para receber o ovo'}</h2><div class="breeding-clock" data-breeding-clock>${breedingTime(breed.eggAt-now)}</div>${eggReady?'<button class="primary-button" id="collect-egg">Colocar ovo na incubadora</button>':`<p>${cooldown?`Próxima alimentação em <b data-feed-clock>${breedingTime(cooldown)}</b>`:'Você pode oferecer uma berry agora.'}</p><div class="breeding-berries">${berries.map(i=>`<button data-breed-berry="${i.id}" ${cooldown?'disabled':''}>${itemImg(i.id,i.name)}<b>${i.name}</b><small>×${state.inventory[i.id]} · -2 horas</small></button>`).join('')||'<p>Sem berries compatíveis na Mochila.</p>'}</div>`}</div>`:`<div class="breeding-egg"><img src="${itemSprite('lucky-egg')}" alt="Ovo Pokémon"><h2>${hatched?'O ovo pode chocar!':'Tempo para chocar'}</h2><div class="breeding-clock" data-breeding-clock>${breedingTime(breed.hatchAt-now)}</div>${hatched?'<button class="primary-button" id="hatch-egg">Chocar ovo</button>':'<p>A incubação dura 6 horas e continua enquanto você estiver fora.</p>'}</div>`}</div>`;root.onclick=e=>{const berry=e.target.closest('[data-breed-berry]');if(berry)feedBreedingBerry(berry.dataset.breedBerry);if(e.target.closest('#collect-egg'))collectBreedingEgg();if(e.target.closest('#hatch-egg'))hatchBreedingEgg()}}
async function startBreeding(firstUid,secondUid){const a=breedingParent(firstUid),b=breedingParent(secondUid),match=breedingCompatibility(a,b);if(!match.compatible)return toast(match.reason);try{const child=await breedingOffspring(match.child.id),breedSorry=!!state.breedSorryReady,duration=breedSorry?10000:86400000;state.breeding={parentA:a.uid,parentB:b.uid,offspringId:child.id,offspringName:child.name,offspringTypes:child.types||[],startedAt:Date.now(),eggAt:Date.now()+duration,lastFedAt:0,hatchAt:null,breedSorry};if(breedSorry)state.breedSorryReady=false;persist();breedingView();toast(`Breeding iniciado! O ovo de ${child.name} ficará pronto em ${breedSorry?'10 segundos':'24 horas'}.`)}catch{toast('Não foi possível identificar a primeira forma evolutiva agora. Tente novamente.')}}
function feedBreedingBerry(id){const breed=state.breeding,item=ITEMS.find(i=>i.id===id),now=Date.now();if(!breed||breed.hatchAt||!item||!state.inventory[id])return;if(now<(breed.lastFedAt||0)+3600000)return toast('Os parceiros só podem receber outra berry após uma hora.');if(!item.favored.some(t=>breed.offspringTypes.includes(t)))return toast('Esta berry não corresponde ao tipo do filhote.');state.inventory[id]--;breed.lastFedAt=now;breed.eggAt=Math.max(now,breed.eggAt-7200000);persist();breedingView();toast(`${item.name} oferecida: 2 horas reduzidas.`)}
function collectBreedingEgg(){const breed=state.breeding;if(!breed||Date.now()<breed.eggAt)return;const duration=breed.breedSorry?10000:21600000;breed.hatchAt=Date.now()+duration;persist();breedingView();toast(`O ovo foi colocado na incubadora. Chocará em ${breed.breedSorry?'10 segundos':'6 horas'}.`)}
async function hatchBreedingEgg(){const breed=state.breeding;if(!breed?.hatchAt||Date.now()<breed.hatchAt)return;try{const a=breedingParent(breed.parentA),b=breedingParent(breed.parentB),match=breedingCompatibility(a,b),sourceId=match.compatible?match.child.id:breed.offspringId,data=await breedingOffspring(sourceId),baby=addCreature(state,{...data,shiny:Math.floor(Math.random()*200)===0},data.name);baby.level=1;baby.xp=0;normalizeTraining(a);normalizeTraining(b);const inherited=[...STAT_KEYS].sort(()=>Math.random()-.5).slice(0,3);for(const key of inherited)baby.ivs[key]=(Math.random()<.5?a:b).ivs[key];baby.iv=averageIv(baby.ivs);state.breeding=null;persist();breedingView();toast(`${baby.shiny?'★ ':''}${baby.name} nasceu com 3 IVs herdados e foi enviado para ${state.active.includes(baby)?'um quarto':'a Box'}!`);playCry(baby.id)}catch{toast('Não foi possível chocar o ovo agora.')}}
function updateBreedingTimer(){if(currentView!=='breeding'||!state?.breeding)return;const breed=state.breeding,now=Date.now(),target=breed.hatchAt||breed.eggAt,clock=$('[data-breeding-clock]');if(clock)clock.textContent=breedingTime(target-now);const feed=$('[data-feed-clock]');if(feed)feed.textContent=breedingTime((breed.lastFedAt||0)+3600000-now);if(!breed.hatchAt&&breed.lastFedAt&&now>=breed.lastFedAt+3600000&&document.querySelector('.breeding-berries button:disabled'))return breedingView();if(now>=target&&!document.querySelector('#collect-egg,#hatch-egg'))breedingView()}
const settingsWithoutVolume=settings;
settings=function(){settingsWithoutVolume();const list=$('#modal-content .settings-list'),toggle=$('#toggle-sound');toggle?.insertAdjacentHTML('afterend',`<label class="volume-control">Volume dos gritos: <b id="cry-volume-value">${Math.round((state.cryVolume??.28)*100)}%</b><input id="cry-volume" type="range" min="0" max="100" step="1" value="${Math.round((state.cryVolume??.28)*100)}"></label>`);$('#cry-volume')?.addEventListener('input',e=>{state.cryVolume=+e.target.value/100;$('#cry-volume-value').textContent=`${e.target.value}%`;persist()})};
