const expeditionItems=event=>event.id==='snowstorm'?['aspear-berry','great-ball','super-potion','ultra-ball']:['sitrus-berry','great-ball','hyper-potion','ultra-ball'];
const expeditionReward=(event,chance,result)=>{const mult={severe:0,failure:.15,partial:.65,success:1,great:1.55}[result]??0,difficulty=event.recommendedLevel/10,quality=.75+chance/200,xp=Math.round((90+event.recommendedLevel*18)*mult*quality),coins=Math.round((120+event.recommendedLevel*24)*mult*quality),pool=expeditionItems(event),items={};if(mult>0){const slots=result==='great'?4:result==='success'?3:result==='partial'?2:1;for(let i=0;i<slots;i++){const id=pool[Math.min(i,pool.length-1)],qty=Math.max(1,Math.round((1+difficulty+i*.35)*mult));items[id]=(items[id]||0)+qty}}return{xp,coins,items}};
const expeditionRewardBoard=event=>`<div class="expedition-rewards"><section><h3>Itens e progresso</h3><p><b>XP:</b> ${90+event.recommendedLevel*10}–${Math.round((90+event.recommendedLevel*18)*1.8)}</p><p><b>PokéCoins:</b> ${120+event.recommendedLevel*12}–${Math.round((120+event.recommendedLevel*24)*1.8)}</p><div>${expeditionItems(event).map(id=>`${itemImg(id,ITEMS.find(i=>i.id===id)?.name)}<small>${ITEMS.find(i=>i.id===id)?.name}</small>`).join('')}</div></section><section><h3>Pokémon resgatáveis</h3><div class="possible-pokemon">${event.species.map(spec=>`<figure class="${state.caught.includes(spec.id)?'owned':'unknown'}"><img src="${sprite(spec.id)}" alt="${state.caught.includes(spec.id)?POKEMON_NAMES[spec.id]||`Pokémon #${spec.id}`:'Espécie desconhecida'}"><figcaption>${state.caught.includes(spec.id)?POKEMON_NAMES[spec.id]||`#${spec.id}`:'???'}</figcaption></figure>`).join('')}</div></section></div>`;
const eventCardV2=event=>{const active=state.expeditions.some(exp=>exp.eventId===event.id);return`<article class="event-card event-${event.id}"><small>NÍVEL RECOMENDADO ${event.recommendedLevel}</small><h2>${event.name}</h2><p>${event.subtitle}</p><div><b>Favorecidos</b><span>${event.favored.map(t=>TYPE_LABELS[t]).join(' · ')}</span></div>${expeditionRewardBoard(event)}<button class="primary-button" data-start-event-v2="${event.id}" ${active||state.expeditions.length>=2||state.rescueCenter.length>=20?'disabled':''}>${active?'Expedição ativa':'Preparar expedição'} <span>▶</span></button></article>`};
const expeditionPanelV2=exp=>{const done=Date.now()>=exp.endAt,p=findOwned(exp.pokemonUid),event=EVENTS.find(e=>e.id===exp.eventId);return`<section class="active-expedition ${done?'complete':''}"><small>${done?'EXPEDIÇÃO CONCLUÍDA':exp.accelerated?'PASSE ATIVO · 1 HORA':'EXPEDIÇÃO EM ANDAMENTO'}</small><h2>${event?.name}</h2><div class="expedition-partner"><img src="${spriteFor(p||{id:exp.pokemonId})}" alt=""><div><b>${exp.pokemonName}</b><span>${exp.chance}% de sucesso · ${riskLabel(exp.chance)}</span><span>Recompensa prevista: ${exp.reward.xp} XP · ${exp.reward.coins} PokéCoins</span></div></div>${done?`<button class="primary-button" data-collect-expedition-v2="${exp.expeditionId}">Receber relatório <span>▶</span></button>`:`<div class="expedition-clock" data-exp-clock="${exp.expeditionId}">${breedingTime(exp.endAt-Date.now())}</div>`}</section>`};
async function eventsViewV2(){state.expeditions=state.expeditions||[];const root=$('#view-container');$('#event-dot')?.classList.toggle('show',state.expeditions.some(exp=>Date.now()>=exp.endAt));root.innerHTML=`<div class="view-title"><div><h1>Eventos & Expedições</h1><p>Até duas expedições simultâneas, uma em cada evento.</p></div><span>${state.expeditions.length}/2 ativas · ${state.rescueCenter.length}/20 resgatados</span></div>${state.expeditions.length?`<div class="expedition-slots">${state.expeditions.map(expeditionPanelV2).join('')}</div>`:''}<div class="event-grid">${EVENTS.map(eventCardV2).join('')}</div><section class="rescue-section"><h2>Centro de Resgate</h2><p>Os Pokémon resgatados permanecem aqui até a tentativa de captura.</p>${state.rescueCenter.length?`<div class="rescue-bulk-actions"><button data-select-all-rescues>Selecionar todos</button><button class="danger-button" data-release-selected-rescues disabled>Liberar selecionados (0)</button></div>`:''}<div class="rescue-grid">${state.rescueCenter.map(r=>`<article class="rescue-card ${r.shiny?'shiny-card':''}" data-rescue-card="${r.rescueId}"><label class="rescue-select"><input type="checkbox" data-select-rescue="${r.rescueId}"><span>Selecionar</span></label><img src="${spriteFor(r)}" alt=""><b>${r.shiny?'★ ':''}Pokémon #${r.id}</b><small>${EVENTS.find(e=>e.id===r.eventId)?.name}</small><button data-rescue-v2="${r.rescueId}">Tentar capturar</button><button class="danger-button" data-release-rescue-v2="${r.rescueId}">Liberar</button></article>`).join('')||'<p>Nenhum Pokémon aguardando captura.</p>'}</div></section>`;const updateSelection=()=>{const selected=[...root.querySelectorAll('[data-select-rescue]:checked')],releaseSelected=root.querySelector('[data-release-selected-rescues]'),selectAll=root.querySelector('[data-select-all-rescues]');root.querySelectorAll('[data-rescue-card]').forEach(card=>card.classList.toggle('selected',!!card.querySelector('[data-select-rescue]:checked')));if(releaseSelected){releaseSelected.disabled=!selected.length;releaseSelected.textContent=`Liberar selecionados (${selected.length})`}if(selectAll)selectAll.textContent=selected.length===state.rescueCenter.length?'Desmarcar todos':'Selecionar todos'};root.onchange=e=>{if(e.target.matches('[data-select-rescue]'))updateSelection()};root.onclick=e=>{const start=e.target.closest('[data-start-event-v2]'),collect=e.target.closest('[data-collect-expedition-v2]'),rescue=e.target.closest('[data-rescue-v2]'),release=e.target.closest('[data-release-rescue-v2]'),selectAll=e.target.closest('[data-select-all-rescues]'),releaseSelected=e.target.closest('[data-release-selected-rescues]');if(start)startExpeditionFlowV2(start.dataset.startEventV2);if(collect)collectExpeditionV2(collect.dataset.collectExpeditionV2);if(rescue)openRescueCapture(rescue.dataset.rescueV2);if(selectAll){const inputs=[...root.querySelectorAll('[data-select-rescue]')],check=!inputs.every(input=>input.checked);inputs.forEach(input=>input.checked=check);updateSelection()}if(releaseSelected){const ids=new Set([...root.querySelectorAll('[data-select-rescue]:checked')].map(input=>input.dataset.selectRescue));if(ids.size&&confirm(`Liberar ${ids.size} Pokémon resgatado${ids.size>1?'s':''}? Esta ação não pode ser desfeita.`)){state.rescueCenter=state.rescueCenter.filter(r=>!ids.has(r.rescueId));persist();eventsViewV2()}}if(release&&confirm('Liberar este Pokémon resgatado?')){state.rescueCenter=state.rescueCenter.filter(r=>r.rescueId!==release.dataset.releaseRescueV2);persist();eventsViewV2()}}}
async function startExpeditionFlowV2(eventId){if(state.expeditions.length>=2)return toast('Os dois slots de expedição estão ocupados.');if(state.expeditions.some(exp=>exp.eventId===eventId))return toast('Este evento já possui uma expedição.');const event=EVENTS.find(e=>e.id===eventId),m=$('#modal');m.showModal();$('#modal-content').innerHTML='<h2>Preparando equipe...</h2>';await hydrateOwnedTypes();const eligible=ownedPokemon().filter(p=>!p.sleepingSince&&!onExpedition(p)&&p.health>=30&&p.energy>=30);$('#modal-content').innerHTML=`<h2>${event.name}</h2><p>Escolha um Pokémon livre com pelo menos 30 de saúde e energia.</p><div class="expedition-picker">${eligible.map(p=>`<button data-expedition-v2-pokemon="${p.uid}"><img src="${spriteFor(p)}" alt=""><b>${p.nickname}</b><small>Nv. ${p.level} · ${compatibilityText(compatibility(p,event))}</small></button>`).join('')||'<p>Nenhum Pokémon está pronto.</p>'}</div>`;m.onclick=e=>{const b=e.target.closest('[data-expedition-v2-pokemon]');if(b)showExpeditionPredictionV2(event,findOwned(b.dataset.expeditionV2Pokemon))}}
function showExpeditionPredictionV2(event,p){const chance=expeditionChance(p,event),preview=expeditionReward(event,chance,'success'),passes=state.inventory['expedition-pass']||0;$('#modal-content').innerHTML=`<h2>Previsão da expedição</h2><div class="prediction-head"><img src="${spriteFor(p)}" alt=""><div><b>${p.nickname} · Nv. ${p.level}</b><span>${compatibilityText(compatibility(p,event))}</span></div></div><div class="prediction-chance risk-${chance<45?'high':chance<65?'medium':'good'}"><small>CHANCE DE SUCESSO</small><strong>${chance}%</strong><b>${riskLabel(chance)}</b></div>${expeditionRewardBoard(event)}<p>Estimativa em um sucesso: <b>${preview.xp} XP · ${preview.coins} PokéCoins</b>. O bônus de EXP dos móveis será aplicado ao receber.</p><label class="expedition-pass-choice"><input id="use-expedition-pass" type="checkbox" ${passes?'':'disabled'}>${itemImg('expedition-pass','Passe de Expedição')} Usar Passe de Expedição e reduzir para 1 hora <b>×${passes}</b></label><button class="primary-button" id="confirm-expedition-v2">Confirmar expedição</button>`;$('#confirm-expedition-v2').onclick=()=>confirmExpeditionV2(event,p,chance,$('#use-expedition-pass').checked)}
function confirmExpeditionV2(event,p,chance,accelerated){if(state.expeditions.length>=2||state.expeditions.some(exp=>exp.eventId===event.id))return;if(onBreeding(p))return toast('Este Pokémon está no Centro de Breeding.');if(accelerated&&!state.inventory['expedition-pass'])return toast('Você não possui um Passe de Expedição.');const plan=planExpedition(event,p,chance),reward=expeditionReward(event,chance,plan.result),duration=accelerated?event.duration/2:event.duration;if(accelerated)state.inventory['expedition-pass']--;state.expeditions.push({expeditionId:`ex-${Date.now()}-${Math.random().toString(16).slice(2)}`,eventId:event.id,pokemonUid:p.uid,pokemonId:p.id,pokemonName:p.nickname,chance,startedAt:Date.now(),endAt:Date.now()+duration,accelerated,reward,rewardVersion:1,...plan});persist();$('#modal').close();eventsViewV2();toast(`${p.nickname} iniciou uma expedição de ${accelerated?'1 hora':'2 horas'}.`)}
