// v7.0: atributos oficiais, amizade e personalidade
const CONVERSATION_COOLDOWN=15*60*1000;
const oppositeResponse={action:'calm',calm:'action',playful:'caring',caring:'playful'};
function natureGreeting(p){const dialogue=NATURE_DIALOGUES[p.nature]||NATURE_DIALOGUES.hardy,tone=friendshipTone(p.friendship??70);if(tone==='distant')return`${p.nickname} observa você com certa cautela.`;if(tone==='best-friend'&&Math.random()<.5)return`${p.nickname} corre para receber você!`;return pickDialogue(dialogue.greetings)}
function conversationTopic(p){for(const[key,limit]of Object.entries({health:35,hunger:30,energy:25,hygiene:30,happiness:35}))if(p[key]<limit){const condition=CONDITION_DIALOGUES[key];return{question:pickDialogue(condition.questions),preferred:condition.preferred,avoid:condition.avoid,need:key}}const nature=natureFor(p.nature),dialogue=NATURE_DIALOGUES[nature.id]||NATURE_DIALOGUES.hardy;return{question:pickDialogue(dialogue.questions),preferred:nature.likes,avoid:oppositeResponse[nature.likes],need:null}}
function conversationResponses(){return Object.entries(RESPONSE_LABELS).map(([type,labels])=>({type,label:pickDialogue(labels)})).sort(()=>Math.random()-.5)}
let conversationAnswerTimer=null;
function stopConversationAnswerRotation(){if(conversationAnswerTimer){clearInterval(conversationAnswerTimer);conversationAnswerTimer=null}}
function openPokemonConversation(p){if(p.sleepingSince)return toast(`${p.nickname} está dormindo.`);if(onExpedition(p)||onBreeding(p)||onBattleChallenge(p))return toast(`${p.nickname} não está disponível para conversar agora.`);const elapsed=Date.now()-(p.lastConversationAt||0);if(elapsed<CONVERSATION_COOLDOWN){const mins=Math.max(1,Math.ceil((CONVERSATION_COOLDOWN-elapsed)/60000));return toast(`${p.nickname} quer um tempinho. Tente conversar novamente em ${mins} min.`)}normalizeTraining(p);stopConversationAnswerRotation();const topic=conversationTopic(p),nature=natureFor(p.nature),m=$('#modal');$('#modal-content').innerHTML=`<div class="conversation-head"><img src="${spriteFor(p)}" alt="${p.nickname}"><div><h2>Conversar com ${p.nickname}</h2><small>Natureza ${nature.name} · personalidade ${nature.personality}</small></div></div><div class="conversation-bubble">“${topic.question}”</div><div class="conversation-answers"></div><div class="conversation-rotation"><small>Novas respostas aparecem a cada 12 segundos.</small><button id="rotate-conversation-answers">Trocar respostas</button></div>`;const renderResponses=()=>{const root=$('#modal-content .conversation-answers');if(!root)return stopConversationAnswerRotation();root.innerHTML=conversationResponses().map(r=>`<button data-conversation-answer="${r.type}">${r.label}</button>`).join('')};renderResponses();conversationAnswerTimer=setInterval(renderResponses,12000);m.showModal();$('#rotate-conversation-answers').onclick=renderResponses;$('#modal-content').onclick=e=>{const answer=e.target.closest('[data-conversation-answer]');if(!answer)return;stopConversationAnswerRotation();const type=answer.dataset.conversationAnswer,personalityMatch=type===nature.likes,needMatch=type===topic.preferred,clash=type===topic.avoid||type===oppositeResponse[nature.likes];let delta=needMatch?6:personalityMatch?4:clash?-4:1;if(topic.need&&type===nature.likes&&!clash)delta=Math.max(delta,2);p.friendship=clampFriendship((p.friendship??70)+delta);p.happiness=clamp(p.happiness+(delta>0?Math.min(4,delta):delta));p.lastConversationAt=Date.now();persist();const reaction=dialogueReaction({natureId:nature.id,delta,friendship:p.friendship,condition:topic.need});$('#modal-content').innerHTML=`<div class="conversation-result"><img src="${spriteFor(p)}" alt="${p.nickname}"><h2>${delta>0?`Amizade +${delta}`:`Amizade ${delta}`}</h2><p>${reaction}</p><small>Amizade atual: ${Math.round(p.friendship)}/255</small><button class="primary-button" id="finish-conversation">Continuar</button></div>`;$('#finish-conversation').onclick=()=>{m.close();home()}}}
const helpWithoutStatsAndConversation=showHelp;showHelp=function(){helpWithoutStatsAndConversation();$('#modal-content').insertAdjacentHTML('beforeend','<section><b>Atributos de batalha</b><p>Cada Pokémon possui IVs e EVs separados para os seis atributos. Nível, base stats, natureza, IVs e EVs definem os valores usados nas batalhas. Cada atributo aceita até 252 EVs, com limite total de 510.</p></section><section><b>Natureza e amizade</b><p>A natureza aumenta um atributo e reduz outro, além de influenciar a personalidade e as respostas do Pokémon. Converse na Casa a cada 15 minutos: suas escolhas podem aumentar ou diminuir a amizade, cujo máximo é 255.</p></section>')};

