function challengeTeamPicker(mode){ensureChallengeState();const max=mode==='dungeon'?3:1,eligible=challengeEligible(),m=$('#modal');$('#modal-content').innerHTML=`<h2>${mode==='dungeon'?'Dungeon Infinita':'Rota de Reide'}</h2><p>${mode==='dungeon'?'Escolha até três Pokémon. O HP continuará entre as salas até toda a equipe desmaiar.':'Escolha um Pokémon para enfrentar cinco guardiões e o boss final.'}</p><div class="gym-team-picker">${eligible.map((p,i)=>`<label><input type="checkbox" value="${p.uid}" ${i===0?'checked':''}><img src="${spriteFor(p)}" alt=""><b>${p.nickname}</b><small>Nv. ${p.level}</small></label>`).join('')||'<p>Nenhum Pokémon está disponível.</p>'}</div><button class="primary-button" id="confirm-challenge-team" ${eligible.length?'':'disabled'}>${mode==='dungeon'?'Entrar na Dungeon':'Usar Passe e entrar'}</button>`;m.showModal();m.querySelectorAll('input').forEach(input=>input.onchange=()=>{const checked=[...m.querySelectorAll('input:checked')];if(checked.length>max){input.checked=false;toast(`Escolha no máximo ${max} Pokémon${max>1?'':' apenas'}.`)}});$('#confirm-challenge-team').onclick=()=>{const ids=[...m.querySelectorAll('input:checked')].map(x=>x.value);if(!ids.length)return toast('Escolha pelo menos um Pokémon.');if(mode==='raid'&&!state.inventory['raid-pass'])return toast('Você precisa de um Passe de Reide.');m.close();beginBattleChallenge(mode,ids)}}
function beginBattleChallenge(mode,teamUids){ensureChallengeState();const team=teamUids.map(findOwned).filter(Boolean),average=team.reduce((n,p)=>n+p.level,0)/team.length,hpByUid=Object.fromEntries(team.map(p=>[p.uid,100]));if(mode==='dungeon'){state.battleChallenge={mode,teamUids,hpByUid,stage:0,turns:0,currentEnemyId:chooseWild(),averageLevel:average,startedAt:Date.now()}}else{const boss=chooseRaidBoss(),route=Array.from({length:5},(_,i)=>({id:chooseWild(),level:raidLevel(average,i+1)}));route.push({id:boss.id,level:raidLevel(average,6,true),boss:true,category:boss.category,shiny:Math.floor(Math.random()*200)===0});state.inventory['raid-pass']--;state.battleChallenge={mode,teamUids,hpByUid,stage:0,turns:0,route,boss,averageLevel:average,startedAt:Date.now()}}persist();resumeBattleChallenge()}
