async function resumeBattleChallenge(){ensureChallengeState();const run=state.battleChallenge;if(!run)return battleView();toast('Preparando o desafio...');try{const team=run.teamUids.map(findOwned).filter(Boolean),fighters=await Promise.all(team.map(p=>challengeFighter(p,run.hpByUid[p.uid],run.statVersion)));let enemies;if(run.mode==='dungeon'){const spec={id:run.currentEnemyId||chooseWild(),level:dungeonLevel(run.averageLevel,run.stage+1)};run.currentEnemyId=spec.id;enemies=[await challengeEnemy(spec)]}else enemies=await Promise.all(run.route.map(challengeEnemy));battle={type:run.mode,team:fighters,playerIndex:Math.max(0,fighters.findIndex(x=>x.hp>0)),enemyTeam:enemies,enemyIndex:run.mode==='raid'?run.stage:0,log:run.mode==='dungeon'?`Sala ${run.stage+1}: a ameaça continua crescendo!`:`Etapa ${run.stage+1}/6 da Rota de Reide.`,busy:false,turns:run.turns||0};run.statVersion=2;syncBattleChallenge();drawBattle();playCry(currentEnemy().id)}catch{toast('Não foi possível preparar este desafio agora.')}}
function syncBattleChallenge(){const run=state.battleChallenge;if(!run||!battle||!['dungeon','raid'].includes(battle.type))return;run.statVersion=2;run.hpByUid=Object.fromEntries(battle.team.map(slot=>[slot.p.uid,slot.hp]));run.turns=battle.turns||0;if(battle.type==='raid')run.stage=battle.enemyIndex;persist()}
function dungeonFinish(){const run=state.battleChallenge,rooms=run?.stage||0,passes=dungeonPassReward(rooms);ensureChallengeState();state.challengeStats.dungeonRuns++;state.challengeStats.dungeonBest=Math.max(state.challengeStats.dungeonBest,rooms);if(passes)state.inventory['raid-pass']+=passes;state.battleChallenge=null;persist();setTimeout(()=>toast(passes?`Dungeon encerrada na sala ${rooms}! Você recebeu ${passes} Passe${passes>1?'s':''} de Reide.`:`Dungeon encerrada na sala ${rooms}. Alcance a sala 5 para obter um Passe de Reide.`),50)}
