const drawBattleBeforeChallenges=drawBattle;drawBattle=function(){drawBattleBeforeChallenges();if(!battle||!['dungeon','raid'].includes(battle.type))return;const run=state.battleChallenge,title=$('#view-container .view-title h1'),counter=$('#view-container .view-title>span');if(title)title.textContent=battle.type==='dungeon'?`Dungeon · Sala ${run.stage+1}`:battle.enemyIndex===5?'Rota de Reide · Boss Final':`Rota de Reide · Guardião ${battle.enemyIndex+1}/5`;if(counter)counter.textContent=battle.type==='dungeon'?`${run.stage} vitórias · dificuldade ${Math.round(currentEnemy().level)}`:`Etapa ${battle.enemyIndex+1}/6 · ${battle.turns||0} turnos`;$('#view-container .battle-team')?.insertAdjacentHTML('beforebegin',`<div class="challenge-progress"><span style="width:${battle.type==='dungeon'?Math.min(100,(run.stage%10)*10):(battle.enemyIndex+1)/6*100}%"></span></div>`);const flee=$('#flee');flee.textContent='Abandonar desafio';flee.onclick=()=>{battle.challengeForfeit=true;state.battleChallenge=null;battleAftercare(false);battle=null;persist();battleView();toast('Desafio abandonado. Nenhuma recompensa foi concedida.')}};
