const enemyDefeatedBeforeChallenges=enemyDefeated;enemyDefeated=function(){if(!battle||!['dungeon','raid'].includes(battle.type))return enemyDefeatedBeforeChallenges();const run=state.battleChallenge,victoryTypes=[...new Set(battle.team.flatMap(slot=>slot.data.types||[]))];awardDefeatedEvs(currentEnemy());progressMissions('battleWin',{types:victoryTypes});if(battle.type==='raid'){if(battle.enemyIndex>=battle.enemyTeam.length-1)return winBattle();run.stage=battle.enemyIndex+1;for(const slot of battle.team)if(slot.hp>0)slot.hp=Math.min(slot.maxHp,slot.hp+Math.ceil(slot.maxHp*.12));battle.enemyIndex++;syncBattleChallenge();battle.busy=false;battle.log=`Guardião vencido! Uma energia restaurou 12% do HP. Próxima etapa!`;drawBattle();playCry(currentEnemy().id);return}run.stage++;state.coins+=25+run.stage*8;for(const slot of battle.team)if(slot.hp>0)slot.hp=Math.min(slot.maxHp,slot.hp+Math.ceil(slot.maxHp*.08));run.hpByUid=Object.fromEntries(battle.team.map(slot=>[slot.p.uid,slot.hp]));run.currentEnemyId=chooseWild();persist();battle.busy=true;battle.log=`Sala ${run.stage} vencida! Preparando a próxima ameaça...`;drawBattle();challengeEnemy({id:run.currentEnemyId,level:dungeonLevel(run.averageLevel,run.stage+1)}).then(enemy=>{if(!battle||battle.type!=='dungeon')return;battle.enemyTeam=[enemy];battle.enemyIndex=0;battle.busy=false;battle.log=`Sala ${run.stage+1}: o adversário está ainda mais forte.`;drawBattle();playCry(enemy.id)}).catch(()=>{battle.busy=false;toast('Não foi possível carregar a próxima sala. Tente novamente.')})};
