function drawRaidBossCapture(){const e=state.raidCapture;if(!e)return battleView();const category=RAID_CATEGORY_LABELS[e.category]||'Raro';$('#view-container').innerHTML=`<div class="view-title"><div><h1>Captura do Boss</h1><p>${category} · ${e.shiny?'★ SHINY · ':''}${e.name}</p></div><span>${e.balls} Premier Balls</span></div><div class="raid-capture panel"><div class="capture-ring ${chanceClass(e.chance)}"><span>${Math.round(e.chance*100)}%</span></div><img class="wild-sprite ${e.shiny?'shiny-sparkle':''}" src="${spriteFor(e)}" alt="${e.name}"><h2>${e.shiny?'★ ':''}${e.name}</h2><p>Cada Premier Ball possui ${Math.round(e.chance*100)}% de chance. As bolas desta rota expiram ao sair.</p><div class="raid-ball-count">${itemImg('premier-ball','Premier Ball')}<b>×${e.balls}</b></div><button class="primary-button" id="throw-raid-ball" ${e.balls?'':'disabled'}>Lançar Premier Ball</button><button class="secondary-button" id="leave-raid-boss">Encerrar tentativa</button></div>`;$('#throw-raid-ball').onclick=throwRaidPremierBall;$('#leave-raid-boss').onclick=()=>{if(confirm('Encerrar a captura? As Premier Balls restantes serão perdidas.')){state.raidCapture=null;persist();battleView()}}}
