// v7.4: áreas de batalha por tipo e nível
function openBattleAreas(){const m=$('#modal');$('#modal-content').innerHTML=`<h2>Áreas de Batalha</h2><p>Escolha o território e a faixa dos três adversários. Use as fraquezas dos tipos locais para montar sua equipe.</p><div class="battle-area-grid">${BATTLE_AREAS.map(area=>`<article><span class="battle-area-icon">${area.icon}</span><h3>${area.name}</h3><p>${area.description}</p><div class="battle-area-types">${area.types.map(type=>`<span>${typeIcons([type])}${TYPE_LABELS[type]}</span>`).join('')}</div><small>Vantagens recomendadas: ${area.advantage.map(type=>TYPE_LABELS[type]).join(' · ')}</small><label>Faixa de nível<select data-area-level="${area.id}">${LEVEL_RANGES.map((range,i)=>`<option value="${i}" ${state.pokemon.level>=range.min&&state.pokemon.level<=range.max?'selected':''}>Níveis ${range.min}–${range.max}</option>`).join('')}</select></label><button class="primary-button" data-enter-area="${area.id}">Montar equipe</button></article>`).join('')}</div>`;m.showModal();$('#modal-content').onclick=e=>{const button=e.target.closest('[data-enter-area]');if(!button)return;const area=battleArea(button.dataset.enterArea),index=Number($(`[data-area-level="${area.id}"]`).value),range=LEVEL_RANGES[index];chooseAreaTeam(area,range)}}
