async function launchAreaBattle(area,range,team){toast(`Entrando em ${area.name}...`);const specs=areaOpponents(area,range,3);try{const[fighters,enemies]=await Promise.all([Promise.all(team.map(playerBattleSlot)),Promise.all(specs.map(enemyBattleSlot))]);battle={type:'area',area,range,team:fighters,playerIndex:0,enemyTeam:enemies,enemyIndex:0,log:`Você entrou em ${area.name}. Prepare-se para três batalhas!`,busy:false,turns:0};drawBattle();playCry(currentEnemy().id)}catch{toast('Não foi possível preparar esta área agora.')}}
const battleViewWithoutAreas=battleView;battleView=async function(){await battleViewWithoutAreas();if(battle||state.battleChallenge||state.raidCapture)return;const grid=$('#view-container .cards-grid');if(!grid||$('#battle-areas-card'))return;grid.insertAdjacentHTML('afterbegin',`<article class="battle-card battle-areas-card" id="battle-areas-card"><span class="battle-area-icon">🗺️</span><h2>Áreas de Batalha</h2><p>Explore territórios por tipagem e escolha adversários do nível 5 ao 100.</p><small>6 áreas · 18 tipos · equipes de até 3</small><button class="primary-button" id="open-battle-areas">Explorar áreas</button></article>`);$('#open-battle-areas').onclick=openBattleAreas};
const drawBattleWithoutAreas=drawBattle;drawBattle=function(){drawBattleWithoutAreas();if(battle?.type!=='area')return;const title=$('#view-container .view-title h1'),subtitle=$('#view-container .view-title p'),counter=$('#view-container .view-title>span');if(title)title.textContent=`${battle.area.icon} ${battle.area.name}`;if(subtitle)subtitle.textContent=`Tipos locais: ${battle.area.types.map(type=>TYPE_LABELS[type]).join(' · ')}`;if(counter)counter.textContent=`Níveis ${battle.range.min}–${battle.range.max} · Rival ${battle.enemyIndex+1}/3`};
