// v7.5: distribuição de XP e áreas infinitas
function ensureExpDevices(){state.expAll=!!state.expAll;state.inventory['exp-share']=state.inventory['exp-share']||0;state.inventory['exp-all']=state.inventory['exp-all']||0;for(const p of ownedPokemon())p.expShare=!!p.expShare}
function activityXpMultiplier(){const bonus=state.furniture.reduce((sum,id)=>sum+(ITEMS.find(item=>item.id===id)?.expBonus||0),0),lucky=state.furniture.includes('study-lamp')?2.5:1;return lucky*(1+bonus)}
function awardActivityXp(source,baseXp){ensureExpDevices();if(!source)return 0;const awards=calculateExperienceAwards({baseXp,sourceUid:source.uid,active:state.active,expAll:state.expAll,activityMultiplier:activityXpMultiplier()}),sourceReceived=source.level<100?awards.source:0;if(sourceReceived)grantXpToPokemon(source,sourceReceived);for(const[uid,xp]of Object.entries(awards.receivers)){const receiver=findOwned(uid);if(receiver?.level<100)grantXpToPokemon(receiver,xp)}return sourceReceived}
gainXp=function(xp){const p=state.pokemon;if(xp===12)p.friendship=clampFriendship((p.friendship??70)-5);return awardActivityXp(p,xp)};
gainExpeditionXp=function(p,xp){return awardActivityXp(p,xp)};
const useUtilityWithoutExpDevices=useUtility;useUtility=function(id){ensureExpDevices();if(id==='exp-all'){if(state.expAll)return toast('O Exp. All já está ativo nesta jornada.');if(!state.inventory[id])return;state.inventory[id]--;state.expAll=true;persist();inventory();return toast('Exp. All ativado! Todos os outros quartos receberão 150% do XP-base.')}if(id==='exp-share')return openExpSharePicker();return useUtilityWithoutExpDevices(id)};
function openExpSharePicker(){if(!state.inventory['exp-share'])return;const available=state.active.filter(p=>!p.expShare),m=$('#modal');$('#modal-content').innerHTML=`<h2>Equipar Exp. Share</h2><p>Escolha um quarto. Quando este Pokémon não estiver em uso, ele receberá 80% do XP ganho pelo parceiro.</p><div class="exp-device-picker">${available.map(p=>`<button data-equip-exp-share="${p.uid}"><img src="${spriteFor(p)}" alt="${p.name}"><span><b>${p.nickname}</b><small>${p.uid===state.pokemon.uid?'Em uso agora · efeito começa ao trocar':'Quarto ativo · Nv. '+p.level}</small></span></button>`).join('')||'<p>Todos os quartos ocupados já possuem Exp. Share.</p>'}</div>`;m.showModal();$('#modal-content').onclick=e=>{const button=e.target.closest('[data-equip-exp-share]');if(!button||!state.inventory['exp-share'])return;const p=findOwned(button.dataset.equipExpShare);if(!p||p.expShare)return;state.inventory['exp-share']--;p.expShare=true;persist();m.close();if(currentView==='rooms')rooms();if(currentView==='inventory')inventory();toast(`Exp. Share equipado no quarto de ${p.nickname}.`)}}
const inventoryWithoutExpDevices=inventory;inventory=function(){ensureExpDevices();inventoryWithoutExpDevices();document.querySelectorAll('.inventory-card').forEach(card=>{const name=card.querySelector('h3')?.textContent;if(!['Exp. Share','Exp. All'].includes(name)||card.querySelector('[data-use-inventory]'))return;const id=name==='Exp. Share'?'exp-share':'exp-all',button=document.createElement('button');button.dataset.useInventory=id;button.textContent=id==='exp-all'&&state.expAll?'Ativo':'Usar';button.disabled=id==='exp-all'&&state.expAll;card.append(button)})};
const changeShopCartWithoutExpDevices=changeShopCart;changeShopCart=function(id,change){ensureExpDevices();if(id==='exp-all'&&change>0&&(state.expAll||state.inventory['exp-all']||shopCart['exp-all']))return toast('O Exp. All só pode ser adquirido uma vez.');return changeShopCartWithoutExpDevices(id,change)};
const roomsWithoutExpDevices=rooms;rooms=function(){ensureExpDevices();roomsWithoutExpDevices();const title=$('#view-container .view-title');title?.insertAdjacentHTML('afterend',`<section class="exp-system-summary"><div>${itemImg('exp-share','Exp. Share')}<span><b>Exp. Share</b><small>${state.active.filter(p=>p.expShare).length} quarto(s) equipado(s) · 80% do ganho real</small></span></div><div>${itemImg('exp-all','Exp. All')}<span><b>Exp. All</b><small>${state.expAll?'ATIVO · 150% do XP-base nos outros quartos':'Não ativado'}</small></span></div><div>${itemImg('lucky-egg','Lucky Egg')}<span><b>Lucky Egg</b><small>${state.furniture.includes('study-lamp')?'ATIVO · XP ×2,5':'Instale a Luminária Lucky Egg'}</small></span></div></section>`);document.querySelectorAll('.poke-room').forEach((room,index)=>{const p=state.active[index];if(p?.expShare)room.insertAdjacentHTML('afterbegin','<span class="exp-share-badge">EXP. SHARE · 80%</span>')})};
chooseAreaTeam=function(area,range){const p=state.pokemon,m=$('#modal'),unavailable=p.sleepingSince||onExpedition(p)||onBreeding(p)||onBattleChallenge(p)||p.health<=0;$('#modal-content').innerHTML=`<h2>${area.icon} ${area.name}</h2><p>Esta exploração usa somente o parceiro do quarto atualmente em uso e continua até ele desmaiar ou você decidir sair.</p><div class="area-solo-partner"><img src="${spriteFor(p)}" alt="${p.name}"><span><b>${p.nickname}</b><small>${p.name} · Nv. ${p.level} · Faixa inimiga ${range.min}–${range.max}</small></span></div><div class="area-recommendation"><b>Tipos recomendados</b><span>${area.advantage.map(type=>`${typeIcons([type])}${TYPE_LABELS[type]}`).join('')}</span></div>${unavailable?'<p class="warning-box">Este parceiro está indisponível. Escolha outro quarto ou cuide dele antes de entrar.</p>':''}<button class="primary-button" id="confirm-area-team" ${unavailable?'disabled':''}>Iniciar sequência infinita</button><button class="secondary-button" id="back-to-areas">Voltar às áreas</button>`;$('#back-to-areas').onclick=openBattleAreas;$('#confirm-area-team').onclick=()=>{m.close();launchAreaBattle(area,range,[p])}};
launchAreaBattle=async function(area,range){const p=state.pokemon;toast(`Entrando em ${area.name}...`);const spec=areaOpponents(area,range,1)[0];try{const[fighter,enemy]=await Promise.all([playerBattleSlot(p),enemyBattleSlot(spec)]);battle={type:'area',area,range,team:[fighter],playerIndex:0,enemyTeam:[enemy],enemyIndex:0,areaWins:0,log:`Você entrou em ${area.name}. A sequência continua enquanto ${p.nickname} resistir!`,busy:false,turns:0};drawBattle();playCry(currentEnemy().id)}catch{toast('Não foi possível preparar esta área agora.')}};
const enemyDefeatedWithoutInfiniteAreas=enemyDefeated;enemyDefeated=function(){if(!battle||battle.type!=='area')return enemyDefeatedWithoutInfiniteAreas();const defeated=currentEnemy(),reward=areaBattleRewards({level:defeated.level,baseExperience:defeated.data.baseExperience,streak:battle.areaWins}),receivedXp=gainXp(reward.xp);awardDefeatedEvs(defeated);state.coins+=reward.coins;battle.areaWins++;progressMissions('battleWin',{types:battle.team[0].data.types||[]});progressMissions('npcWin');state.seen=[...new Set([...state.seen,defeated.id])];persist();battle.busy=true;battle.log=`Vitória ${battle.areaWins}! +${receivedXp.toLocaleString('pt-BR')} XP${receivedXp!==reward.xp?` (${reward.xp.toLocaleString('pt-BR')} base)`:''} · +${reward.coins.toLocaleString('pt-BR')} PokéCoins${reward.streakBonus>1?` · sequência ×${reward.streakBonus.toFixed(2).replace('.',',')}`:''}.`;drawBattle();const spec=areaOpponents(battle.area,battle.range,1)[0];enemyBattleSlot(spec).then(enemy=>{if(!battle||battle.type!=='area')return;battle.enemyTeam=[enemy];battle.enemyIndex=0;battle.busy=false;battle.log=`Sequência ${battle.areaWins}: ${enemy.data.name} apareceu! Você pode continuar ou sair com as recompensas.`;drawBattle();playCry(enemy.id)}).catch(()=>{battle.busy=false;drawBattle();toast('Não foi possível carregar o próximo adversário. Você pode sair em segurança.')})};
const drawBattleWithoutInfiniteAreas=drawBattle;drawBattle=function(){drawBattleWithoutInfiniteAreas();if(battle?.type!=='area')return;const counter=$('#view-container .view-title>span'),flee=$('#flee');if(counter)counter.textContent=`Níveis ${battle.range.min}–${battle.range.max} · ${battle.areaWins} vitória(s)`;if(flee){flee.textContent=`Sair da área · ${battle.areaWins} vitória(s)`;flee.onclick=()=>{const wins=battle.areaWins;if(wins)battleAftercare(true);battle=null;persist();battleView();toast(`Exploração encerrada com ${wins} vitória${wins===1?'':'s'}.`)}}};
function areaRewardPreview(range){const low=areaBattleRewards({level:range.min,baseExperience:60}),high=areaBattleRewards({level:range.max,baseExperience:240});return`${low.xp.toLocaleString('pt-BR')}–${high.xp.toLocaleString('pt-BR')} XP-base · ${low.coins.toLocaleString('pt-BR')}–${high.coins.toLocaleString('pt-BR')} PC por vitória`}
const openBattleAreasBeforeSoloMode=openBattleAreas;openBattleAreas=function(){openBattleAreasBeforeSoloMode();const intro=$('#modal-content>p');if(intro)intro.textContent='Escolha o território e a faixa dos adversários. A sequência usa somente o parceiro do quarto atualmente em uso.';document.querySelectorAll('[data-enter-area]').forEach(button=>{button.textContent='Usar parceiro atual';const article=button.closest('article'),select=article.querySelector('[data-area-level]'),preview=document.createElement('strong');preview.className='area-reward-preview';const update=()=>preview.textContent=`Recompensa estimada: ${areaRewardPreview(LEVEL_RANGES[Number(select.value)])}`;select.addEventListener('change',update);update();button.before(preview)})};
const battleViewBeforeSoloAreas=battleView;battleView=async function(){await battleViewBeforeSoloAreas();const card=$('#battle-areas-card');if(!card)return;const description=card.querySelector('p'),summary=card.querySelector('small');if(description)description.textContent='Explore territórios por tipagem em sequências infinitas com o parceiro atual.';if(summary)summary.textContent='6 áreas · 18 tipos · 1 parceiro'};
const enemyDefeatedBeforeDungeonXp=enemyDefeated;enemyDefeated=function(){if(battle?.type==='dungeon'){const defeated=currentEnemy(),xp=Math.round(defeated.data.baseExperience*.32+defeated.level*2);gainXp(xp)}return enemyDefeatedBeforeDungeonXp()};
const helpWithoutExpSystem=showHelp;showHelp=function(){helpWithoutExpSystem();$('#modal-content').insertAdjacentHTML('beforeend','<section><b>Sistema de experiência</b><p>O Exp. Share custa 10.000 PC e equipa um quarto, que recebe 80% do ganho real do parceiro. O Exp. All custa 80.000 PC, é permanente e concede 150% do XP-base a todos os outros quartos. A Luminária Lucky Egg custa 15.000 PC e multiplica por 2,5 o XP do Pokémon em uso em todas as atividades.</p></section><section><b>Áreas infinitas</b><p>As Áreas de Batalha usam somente o parceiro atual. Após cada vitória surge outro adversário da faixa escolhida; saia quando quiser ou continue até o Pokémon desmaiar. XP e PokéCoins crescem com o nível da área e com a sequência de vitórias.</p></section>')};
