const redeemCodeWithoutBreedSorry=redeemCode;redeemCode=function(raw){const code=raw.trim().toUpperCase(),feedback=$('#code-feedback');if(code!=='BREEDSORRY')return redeemCodeWithoutBreedSorry(raw);if(state.redeemedCodes.includes(code))return feedback.textContent='Este código já foi resgatado nesta jornada.';state.breedSorryReady=true;state.redeemedCodes.push(code);persist();feedback.textContent='Código aceito! Seu próximo breeding produzirá o ovo em 10 segundos, e a incubação também levará 10 segundos.';const count=$('.view-title>span');if(count)count.textContent=`${state.redeemedCodes.length} resgatados`;toast('BREEDSORRY ativado para o próximo breeding!')};
const breedingViewWithoutBreedSorry=breedingView;breedingView=async function(){await breedingViewWithoutBreedSorry();const titleBadge=$('#view-container .view-title>span');if(!state.breeding&&state.breedSorryReady){if(titleBadge)titleBadge.textContent='BREEDSORRY · 10 segundos';$('#view-container .breeding-selection-summary')?.insertAdjacentHTML('beforebegin','<div class="warning-box"><b>BREEDSORRY disponível</b><br>O próximo breeding produzirá o ovo em 10 segundos e também chocará após 10 segundos de incubação.</div>')}if(state.breeding?.breedSorry){if(titleBadge)titleBadge.textContent=state.breeding.hatchAt?'Incubação rápida · 10s':'Ovo rápido · 10s';const incubation=[...document.querySelectorAll('#view-container .breeding-egg p')].find(p=>p.textContent.includes('incubação dura 6 horas'));if(incubation)incubation.textContent='BREEDSORRY ativo: a incubação leva apenas 10 segundos.'}};
